    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 진통제 처방에서 투약을 보류하고 담당의 확인을 우선한 판단 근거가 구체적인지 확인한다.",
